// Configuration - edit these values
const WATCHLIST = [
  { symbol: 'BTCUSDT', alertAbove: 100000, alertBelow: 90000 },
  { symbol: 'ETHUSDT', alertAbove: 4000, alertBelow: 3000 },
  { symbol: 'SOLUSDT', alertAbove: 200, alertBelow: 150 }
];

// Get static variable store for cooldowns
const store = $getWorkflowStaticData('global');
if (!store.lastAlerts) store.lastAlerts = {};

const alerts = [];
const now = Date.now();
const COOLDOWN_MS = 15 * 60 * 1000; // 15 min cooldown between same alerts

for (const coin of WATCHLIST) {
  try {
    // Fetch price for each symbol
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.bybit.com/v5/market/tickers?category=spot&symbol=${coin.symbol}`,
    });

    const ticker = response.result.list[0];
    const price = parseFloat(ticker.lastPrice);
    const change24h = parseFloat(ticker.price24hPcnt) * 100;
    const volume24h = parseFloat(ticker.turnover24h);

    let alertType = null;

    if (price >= coin.alertAbove) {
      alertType = 'above';
    } else if (price <= coin.alertBelow) {
      alertType = 'below';
    }

    // Check for 24h change > 5%
    if (Math.abs(change24h) > 5) {
      alertType = alertType || 'volatility';
    }

    const alertKey = `${coin.symbol}_${alertType}`;
    const lastAlert = store.lastAlerts[alertKey] || 0;

    if (alertType && (now - lastAlert) > COOLDOWN_MS) {
      store.lastAlerts[alertKey] = now;

      let emoji = '📊';
      let reason = '';
      if (alertType === 'above') { emoji = '🚀'; reason = `выше ${coin.alertAbove}`; }
      if (alertType === 'below') { emoji = '🔻'; reason = `ниже ${coin.alertBelow}`; }
      if (alertType === 'volatility') { emoji = '⚡'; reason = `изменение ${change24h.toFixed(2)}% за 24ч`; }

      alerts.push({
        symbol: coin.symbol,
        price: price,
        change24h: change24h.toFixed(2),
        volume24h: (volume24h / 1e6).toFixed(2),
        emoji: emoji,
        reason: reason,
        alertType: alertType
      });
    }
  } catch (e) {
    // Skip if API error for this symbol
  }
}

if (alerts.length === 0) {
  alerts.push({ skip: true });
}

return alerts.map(a => ({ json: a }));

const alerts = $input.all();

let message = '🔔 <b>Bybit Price Alerts</b>\n\n';

for (const item of alerts) {
  const a = item.json;
  message += `${a.emoji} <b>${a.symbol}</b>\n`;
  message += `   Цена: <code>$${a.price}</code>\n`;
  message += `   24ч: ${a.change24h}%\n`;
  message += `   Объём: $${a.volume24h}M\n`;
  message += `   Причина: ${a.reason}\n\n`;
}

message += `⏱ ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;

return [{ json: { message } }];
